solution:
# 1) Count words starting with 'a'
words = ["apple", "avocado", "banana", "apricot"]
count_a = 0
for w in words:
    if w.startswith("a"):
        count_a += 1
print("words starting with a:", count_a)

# 2) Sum even numbers
nums = [3, 8, 12, 5, 4]
sum_evens = 0
for n in nums:
    if n % 2 == 0:
        sum_evens += n
print("sum evens:", sum_evens)

# 3) Build frequency dict
text = "ada likes algorithms"
counts = {}
for ch in text:
    counts[ch] = counts.get(ch, 0) + 1
print(counts)
